using System.Collections.Concurrent;
using System.Net.Http.Json;
using System.Security.Cryptography;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddSingleton<IIdempotencyStore>(sp =>
    new InMemoryIdempotencyStore(sp.GetRequiredService<TimeProvider>(), TimeSpan.FromHours(24)));

var app = builder.Build();
app.Urls.Add("http://127.0.0.1:0");

// In a real app: after UseExceptionHandler and UseAuthentication (keys are scoped per user).
app.UseMiddleware<IdempotencyMiddleware>();

var paymentsCreated = 0;
app.MapPost("/payments", async (PaymentRequest request) =>
{
    await Task.Delay(200);   // long enough for concurrent duplicates to overlap
    var id = Interlocked.Increment(ref paymentsCreated);
    return Results.Created($"/payments/{id}", new { id, request.Amount, request.Currency });
});

var flakyCalls = 0;
app.MapPost("/flaky", () =>
    Interlocked.Increment(ref flakyCalls) == 1 ? Results.StatusCode(503) : Results.Ok(new { ok = true }));

await app.StartAsync();
using var client = new HttpClient { BaseAddress = new Uri(app.Urls.First()) };
var failures = 0;
var payment = new { amount = 10.5m, currency = "EUR" };

// 1. Sequential duplicate is replayed, the endpoint runs once.
var first = await Post("/payments", payment, "key-1");
var second = await Post("/payments", payment, "key-1");
Check("replay",
    first.StatusCode == System.Net.HttpStatusCode.Created
    && second.StatusCode == System.Net.HttpStatusCode.Created
    && await first.Content.ReadAsStringAsync() == await second.Content.ReadAsStringAsync()
    && first.Headers.Location == second.Headers.Location
    && second.Headers.Contains("Idempotent-Replayed")
    && Volatile.Read(ref paymentsCreated) == 1);

// 2. Same key, different payload.
var mismatch = await Post("/payments", new { amount = 99m, currency = "EUR" }, "key-1");
Check("fingerprint mismatch -> 422", (int)mismatch.StatusCode == 422);

// 3. Concurrent duplicates: one runs, one is told to retry.
var concurrent = await Task.WhenAll(Post("/payments", payment, "key-2"), Post("/payments", payment, "key-2"));
var codes = concurrent.Select(r => (int)r.StatusCode).Order().ToArray();
Check("concurrent duplicate -> 409", codes is [201, 409]);

// 4. No key: no idempotency.
var before = Volatile.Read(ref paymentsCreated);
await Post("/payments", payment, null);
await Post("/payments", payment, null);
Check("no key -> both executed", Volatile.Read(ref paymentsCreated) == before + 2);

// 5. 5xx releases the key so the retry runs again.
var flaky1 = await Post("/flaky", new { }, "key-3");
var flaky2 = await Post("/flaky", new { }, "key-3");
Check("5xx not stored", (int)flaky1.StatusCode == 503 && (int)flaky2.StatusCode == 200
                        && !flaky2.Headers.Contains("Idempotent-Replayed"));

// 6. Invalid key.
var invalid = await Post("/payments", payment, new string('k', 300));
Check("invalid key -> 400", (int)invalid.StatusCode == 400);

Console.WriteLine(failures == 0 ? "ALL PASSED" : $"{failures} FAILED");
await app.StopAsync();

async Task<HttpResponseMessage> Post(string path, object body, string? key)
{
    using var message = new HttpRequestMessage(HttpMethod.Post, path) { Content = JsonContent.Create(body) };
    if (key is not null) message.Headers.Add(IdempotencyMiddleware.HeaderName, key);
    var response = await client.SendAsync(message);
    await response.Content.LoadIntoBufferAsync();
    return response;
}

void Check(string name, bool ok)
{
    if (!ok) failures++;
    Console.WriteLine($"{(ok ? "PASS" : "FAIL")} {name}");
}

// ------------------------------------------------------------------ contracts

public sealed record PaymentRequest(decimal Amount, string Currency);

public sealed record CachedResponse(
    int StatusCode, string? ContentType, IReadOnlyDictionary<string, string> Headers, byte[] Body);

public enum BeginOutcome { Acquired, InProgress, Completed, FingerprintMismatch }

public readonly record struct BeginResult(BeginOutcome Outcome, CachedResponse? Response = null);

public interface IIdempotencyStore
{
    /// Atomically reserves <paramref name="key"/> or reports the state of an existing reservation.
    ValueTask<BeginResult> TryBeginAsync(string key, string fingerprint, CancellationToken ct);

    /// Stores the final response for a reservation owned by the caller.
    ValueTask CompleteAsync(string key, CachedResponse response, CancellationToken ct);

    /// Drops an in-flight reservation so a retry can execute again.
    ValueTask ReleaseAsync(string key, CancellationToken ct);
}

// ------------------------------------------------------------------ in-memory store (single instance only)

public sealed class InMemoryIdempotencyStore(TimeProvider clock, TimeSpan ttl) : IIdempotencyStore
{
    private sealed record Entry(string Fingerprint, CachedResponse? Response, DateTimeOffset ExpiresAt);

    private readonly ConcurrentDictionary<string, Entry> _entries = new();

    public ValueTask<BeginResult> TryBeginAsync(string key, string fingerprint, CancellationToken ct)
    {
        var now = clock.GetUtcNow();
        var fresh = new Entry(fingerprint, null, now + ttl);

        while (true)
        {
            var current = _entries.GetOrAdd(key, fresh);
            if (ReferenceEquals(current, fresh))
                return ValueTask.FromResult(new BeginResult(BeginOutcome.Acquired));

            if (current.ExpiresAt <= now)
            {
                // Expired: compare-and-swap; if another request replaced it first, re-evaluate.
                if (_entries.TryUpdate(key, fresh, current))
                    return ValueTask.FromResult(new BeginResult(BeginOutcome.Acquired));
                continue;
            }

            if (!string.Equals(current.Fingerprint, fingerprint, StringComparison.Ordinal))
                return ValueTask.FromResult(new BeginResult(BeginOutcome.FingerprintMismatch));

            return ValueTask.FromResult(current.Response is null
                ? new BeginResult(BeginOutcome.InProgress)
                : new BeginResult(BeginOutcome.Completed, current.Response));
        }
    }

    public ValueTask CompleteAsync(string key, CachedResponse response, CancellationToken ct)
    {
        if (_entries.TryGetValue(key, out var current) && current.Response is null)
            _entries.TryUpdate(key, current with { Response = response, ExpiresAt = clock.GetUtcNow() + ttl }, current);
        return ValueTask.CompletedTask;
    }

    public ValueTask ReleaseAsync(string key, CancellationToken ct)
    {
        // Remove only our in-flight entry, never a completed one written in the meantime.
        if (_entries.TryGetValue(key, out var current) && current.Response is null)
            _entries.TryRemove(KeyValuePair.Create(key, current));
        return ValueTask.CompletedTask;
    }
}

// ------------------------------------------------------------------ middleware

public sealed class IdempotencyMiddleware(
    RequestDelegate next,
    IIdempotencyStore store,
    ILogger<IdempotencyMiddleware> logger)
{
    public const string HeaderName = "Idempotency-Key";
    private const int MaxKeyLength = 255;
    private static readonly string[] ReplayedHeaders = ["Location", "ETag"];

    public async Task InvokeAsync(HttpContext context)
    {
        var request = context.Request;
        if (!(HttpMethods.IsPost(request.Method) || HttpMethods.IsPatch(request.Method))
            || !request.Headers.TryGetValue(HeaderName, out var values))
        {
            await next(context);
            return;
        }

        var rawKey = values.ToString();
        if (values.Count != 1 || !IsValidKey(rawKey))
        {
            await Results.Problem(statusCode: StatusCodes.Status400BadRequest,
                title: $"Invalid {HeaderName} header.").ExecuteAsync(context);
            return;
        }

        var ct = context.RequestAborted;
        var key = $"{context.User.Identity?.Name ?? "anonymous"}|{rawKey}";
        var fingerprint = await FingerprintAsync(request, ct);

        var begin = await store.TryBeginAsync(key, fingerprint, ct);
        switch (begin.Outcome)
        {
            case BeginOutcome.FingerprintMismatch:
                await Results.Problem(statusCode: StatusCodes.Status422UnprocessableEntity,
                    title: $"{HeaderName} was already used with a different request.").ExecuteAsync(context);
                return;

            case BeginOutcome.InProgress:
                context.Response.Headers.RetryAfter = "1";
                await Results.Problem(statusCode: StatusCodes.Status409Conflict,
                    title: $"A request with this {HeaderName} is still being processed.").ExecuteAsync(context);
                return;

            case BeginOutcome.Completed:
                logger.LogInformation("Replaying stored response for idempotency key {Key}", rawKey);
                await ReplayAsync(context, begin.Response!, ct);
                return;
        }

        // Acquired: run the endpoint once, capturing the body so it can be stored.
        var originalBody = context.Response.Body;
        using var buffer = new MemoryStream();
        context.Response.Body = buffer;
        var stored = false;
        try
        {
            await next(context);

            var response = context.Response;
            if (response.StatusCode < StatusCodes.Status500InternalServerError)
            {
                var headers = ReplayedHeaders
                    .Where(h => response.Headers.ContainsKey(h))
                    .ToDictionary(h => h, h => response.Headers[h].ToString());
                await store.CompleteAsync(key,
                    new CachedResponse(response.StatusCode, response.ContentType, headers, buffer.ToArray()),
                    CancellationToken.None);
                stored = true;
            }

            context.Response.Body = originalBody;
            buffer.Position = 0;
            await buffer.CopyToAsync(originalBody, ct);
        }
        finally
        {
            context.Response.Body = originalBody;
            if (!stored)   // 5xx or exception: let the client retry for real
                await store.ReleaseAsync(key, CancellationToken.None);
        }
    }

    private static bool IsValidKey(string key) =>
        key.Length is > 0 and <= MaxKeyLength
        && key.All(c => char.IsAsciiLetterOrDigit(c) || c is '-' or '_');

    private static async Task<string> FingerprintAsync(HttpRequest request, CancellationToken ct)
    {
        request.EnableBuffering();   // seekable copy, so the endpoint can read the body again
        var bodyHash = await SHA256.HashDataAsync(request.Body, ct);
        request.Body.Position = 0;
        return $"{request.Method} {request.Path}{request.QueryString} {Convert.ToHexString(bodyHash)}";
    }

    private static async Task ReplayAsync(HttpContext context, CachedResponse cached, CancellationToken ct)
    {
        context.Response.StatusCode = cached.StatusCode;
        if (cached.ContentType is not null)
            context.Response.ContentType = cached.ContentType;
        foreach (var (name, value) in cached.Headers)
            context.Response.Headers[name] = value;
        context.Response.Headers["Idempotent-Replayed"] = "true";
        await context.Response.Body.WriteAsync(cached.Body, ct);
    }
}

